const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const axeSource = require('axe-core').source;
  const htmlPath = '/workspace/sandbox/skills/building-accessible-ui/shopping-home-page--framework-react--style-modern/claude-haiku-4.5__s0/index.html';
  const htmlContent = fs.readFileSync(htmlPath, 'utf-8');

  const browser = await chromium.launch();
  const page = await browser.newPage();

  // Test mobile viewport
  await page.setViewportSize({ width: 375, height: 667 });
  await page.setContent(htmlContent, { waitUntil: 'networkidle' });
  await page.waitForTimeout(500);

  await page.addScriptTag({ content: axeSource });

  const results = await page.evaluate(() => {
    return window.axe.run({
      runOnly: {
        type: 'tag',
        values: ['wcag2aa', 'best-practice']
      }
    });
  });

  await browser.close();

  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));

  console.log(`Mobile (375x667): ${wcag.length} WCAG violations, ${results.passes.length} passes`);
  if (wcag.length > 0) {
    console.log(JSON.stringify(wcag, null, 2));
  }

  process.exit(wcag.length > 0 ? 1 : 0);
})();
EOF
